select jsonb_build_object(
'dd_windows',(select count(*)from spot_private.discovery_windows),'dd_allocations',(select count(*)from spot_private.discovery_allocations),'dd_exposures',(select count(*)from spot_private.discovery_exposures),'dd_fairness',(select count(*)from spot_private.discovery_fairness_buckets),'dd_pair_memory',(select count(*)from spot_private.discovery_pair_memory),'dd_policy',(select jsonb_agg(to_jsonb(p))from spot_private.discovery_policy p),'accounts',(select count(*)from auth.users),'profiles',(select count(*)from profiles),'objects',(select count(*)from storage.objects where bucket_id='profile-photos'),
'fixture_auth',(select count(*)from auth.users where id::text like 'fea37000-%'),
'fixture_profiles',(select count(*)from profiles where id::text like 'fea37000-%'),
'fixture_objects',(select count(*)from storage.objects where bucket_id='profile-photos'and name like 'fea37000-%'),
'fixture_ledger',(select count(*)from spot_private.photo_lifecycle_sets where user_id::text like 'fea37000-%'),
'fixture_jobs',(select count(*)from spot_private.photo_upload_jobs where user_id::text like 'fea37000-%'),
'fixture_memberships',(select count(*)from spot_private.tribe_memberships where user_id::text like 'fea37000-%'),
'fixture_presence',(select count(*)from checkins where user_id::text like 'fea37000-%'),
'fixture_intents',(select count(*)from spot_private.spot_v2_intents where sender_id::text like 'fea37000-%'or recipient_id::text like 'fea37000-%'),
'fixture_receipts',(select count(*)from spot_private.spot_v2_operations where sender_id::text like 'fea37000-%'),
'fixture_quota',(select count(*)from spot_private.ora_spot_daily_quota where user_id::text like 'fea37000-%'),
'fixture_matches',(select count(*)from matches where user_a::text like 'fea37000-%'or user_b::text like 'fea37000-%'),
'fixture_messages',(select count(*)from messages where sender_id::text like 'fea37000-%'),
'photo_control',(select jsonb_build_object('phase',phase,'epoch',epoch,'execute',execute_enabled,'scheduler',scheduler_enabled,'cleanup',cleanup_all)from spot_private.photo_cutover_control),
'historical_review',(select count(*)from spot_private.photo_lifecycle_sets where state='review'and user_id::text not like 'fea37000-%'),
'fixture_review',(select count(*)from spot_private.photo_lifecycle_sets where (writer='unknown'or state='review')and user_id::text like 'fea37000-%'),
'fixture_purged_receipts',(select count(*)from spot_private.photo_lifecycle_sets where state='purged'and reserved_bytes=0 and user_id::text like 'fea37000-%'),
'fixture_cleanup_receipts',(select count(*)from spot_private.photo_cleanup_accounts where user_id::text like 'fea37000-%'and state='completed'),
'photo_uncertain',(select count(*)from spot_private.photo_lifecycle_sets where writer in('unknown','review')),
'missing_current',(select count(*)from profiles p where not exists(select 1 from storage.objects o where o.bucket_id='profile-photos'and o.name=p.photo_path)),
'unattributed_objects',(select count(*)from storage.objects o where bucket_id='profile-photos'and not exists(select 1 from spot_private.photo_lifecycle_sets s where o.name in(s.photo_path,s.photo_path||'.thumb.jpg',s.photo_path||'.detail.jpg'))and not exists(select 1 from spot_private.validated_photos v where o.name in(v.photo_path,v.photo_path||'.thumb.jpg',v.photo_path||'.detail.jpg'))and not exists(select 1 from spot_private.photo_assets a where o.name in(a.photo_path,a.thumbnail_path,a.detail_path))and not exists(select 1 from spot_private.photo_upload_jobs j where o.name in(j.photo_path,j.photo_path||'.thumb.jpg',j.photo_path||'.detail.jpg'))and not exists(select 1 from spot_private.photo_cutover_attempts a where o.name in(a.path,a.path||'.thumb.jpg',a.path||'.detail.jpg'))),
'matches',(select count(*)from matches),'messages',(select count(*)from messages),
'control',(select to_jsonb(c)from spot_private.soma_v2_control c)
) evidence;
